/** Invokes `asset-token::update_valuation` (admin, new_valuation). */
export interface AssetTokenUpdateValuationInput {
  admin: string;
  new_valuation: bigint | string;
}
export type AssetTokenUpdateValuationOutput = void;

/** Invokes `asset-token::set_compliance` (admin, compliance). */
export interface AssetTokenSetComplianceInput {
  admin: string;
  compliance: string;
}
export type AssetTokenSetComplianceOutput = void;

/** Issue #10 — set (or clear, with `unlock_ledger = 0`) the holding-period lockup for `holder`. Admin-authenticated. Used both to impose a regulatory-exemption holding period (e.g. a 12-month lockup) and, by setting `unlock_ledger` back to `0` or to an earlier ledger, to grant a partial/early release under a court order or approved exemption. Does not affect `mint` or `initialize`. */
export interface AssetTokenSetLockupInput {
  admin: string;
  holder: string;
  unlock_ledger: number;
}
export type AssetTokenSetLockupOutput = void;

/** The ledger sequence at/after which `holder` may transfer or burn. `0` means no lockup is in effect. */
export interface AssetTokenGetLockupInput {
  holder: string;
}
