/** Invokes `asset-token::get_metadata` (no parameters). Returns `AssetMetadata`. */
export interface AssetTokenGetMetadataInput {
}
export type AssetTokenGetMetadataOutput = AssetTokenAssetMetadata;

/** Current contract ABI version, polled by the off-chain indexer. */
export interface AssetTokenVersionInput {
}
export type AssetTokenVersionOutput = number;

/** Issue #12 — on-chain clawback engine. Deliberately implemented as a standalone path, NOT on top of `transfer`: a clawback is an admin-only, legally-authorized recovery mechanism (court order, lost-key recovery, regulatory enforcement) that must be able to succeed precisely when the holder cannot or will not cooperate — for example, their address has since been suspended in compliance, or they refuse to sign. Routing this through `transfer` would force it through `from.require_auth()` and the sender-compliance check, which are exactly the two things a clawback needs to bypass. It still validates the source balance (reusing `Error::InsufficientBalance`, since the failure mode is identical to a transfer's — see the PR description for why a new error code was not added here), and emits a dedicated `clawback` event so the recovery is fully auditable on-chain. Total supply is unchanged: recovered units are credited to the administrator so every unit of supply remains backed by an account balance. */
export interface AssetTokenClawbackInput {
  admin: string;
  from: string;
  amount: bigint | string;
}
export type AssetTokenClawbackOutput = void;

/** Issue #11 — migrate this contract to a new WASM build without losing storage. Reuses `Error::Unauthorized` (3), already the admin-mismatch error for every other admin-gated call on this contract; no new error code is needed. */
export interface AssetTokenUpgradeInput {
  admin: string;
  new_wasm_hash: string;
}
export type AssetTokenUpgradeOutput = void;

